parameters.jsCode:
const post = $('Content creator').item.json.output;

// Hashtags from the model (array, or a comma/space separated string if the model ignored the format)
let raw = $json.output?.hashtags ?? $json.output ?? [];
if (typeof raw === 'string') raw = raw.split(/[,\s]+/);
if (!Array.isArray(raw)) raw = [];

const MIN_TAGS = 8;   // pad with defaults up to this many
const MAX_TAGS = 10;  // never post more than this many
const fallback = ['#AI', '#Automation', '#LinkedInGrowth', '#ContentCreation', '#Solopreneur',
                  '#NoCode', '#FutureOfWork', '#PersonalBranding', '#Productivity', '#DigitalMarketing'];

const clean = t => '#' + String(t).trim().replace(/^#+/, '').replace(/[^A-Za-z0-9_]/g, '');
const seen = new Set();
const tags = [];
const add = t => {
  const c = clean(t);
  if (c.length < 3) return;
  const k = c.toLowerCase();
  if (seen.has(k)) return;
  seen.add(k);
  tags.push(c);
};

for (const t of raw) { if (tags.length < MAX_TAGS) add(t); }
for (const t of fallback) { if (tags.length < MIN_TAGS) add(t); }

return {
  json: {
    post_text: post['post content'] + '\n\n' + tags.join(' '),
    post_title: post['post title'],
    image_description: post['image description'],
    hashtags: tags,
  },
};

// --- settings you may want to change ---
const CHECKPOINT = '';   // e.g. 'sd_xl_base_1.0.safetensors'. Empty = first checkpoint ComfyUI has installed
const WIDTH = 768, HEIGHT = 400;   // multiples of 8. Use 1024 x 536 for SDXL models
const STEPS = 20, CFG = 7;
// ---------------------------------------

const info = $json.CheckpointLoaderSimple?.input?.required?.ckpt_name;
const installed = Array.isArray(info?.[0]) ? info[0] : (info?.[1]?.options ?? []);
const ckpt = CHECKPOINT || installed[0];
if (!ckpt) throw new Error('No checkpoint found in ComfyUI. Put a .safetensors model in ComfyUI/models/checkpoints and restart/refresh ComfyUI.');

const b = $('Build final post').first().json;
const subject = String(b.image_description || b.post_title).slice(0, 400);

return {
  json: {
    checkpoint: ckpt,
    body: {
      prompt: {
        '3': { class_type: 'KSampler', inputs: {
          seed: Math.floor(Math.random() * 1e12), steps: STEPS, cfg: CFG,
          sampler_name: 'euler', scheduler: 'normal', denoise: 1,
          model: ['4', 0], positive: ['6', 0], negative: ['7', 0], latent_image: ['5', 0] } },
        '4': { class_type: 'CheckpointLoaderSimple', inputs: { ckpt_name: ckpt } },
        '5': { class_type: 'EmptyLatentImage', inputs: { width: WIDTH, height: HEIGHT, batch_size: 1 } },
        '6': { class_type: 'CLIPTextEncode', inputs: {
          text: subject + ', clean modern professional illustration for a LinkedIn post, high quality, no text',
          clip: ['4', 1] } },
        '7': { class_type: 'CLIPTextEncode', inputs: {
          text: 'text, words, letters, watermark, logo, blurry, low quality, distorted, deformed',
          clip: ['4', 1] } },
        '8': { class_type: 'VAEDecode', inputs: { samples: ['3', 0], vae: ['4', 2] } },
        '9': { class_type: 'SaveImage', inputs: { filename_prefix: 'n8n_linkedin', images: ['8', 0] } },
      },
    },
  },
};

const MAX_POLLS = 90;   // 90 x 8s = 12 minutes before giving up

const id = $('Queue ComfyUI image').first().json.prompt_id;
const h = $input.first().json[id];

if (h?.status?.status_str === 'error') {
  throw new Error('ComfyUI reported an error while generating the image. Check the ComfyUI container logs.');
}

const images = Object.values(h?.outputs ?? {}).flatMap(o => o.images ?? []);
if (images.length) return { json: { done: true, image: images[0] } };

if ($runIndex >= MAX_POLLS) {
  throw new Error('Timed out waiting for ComfyUI. Check the ComfyUI container (queue, memory, model loading).');
}
return { json: { done: false } };
